import React from 'react';
import { AlertTriangle, CheckCircle, X } from 'lucide-react';

const SciFiAlert = ({ type = 'success', title, message, onClose, onConfirm }) => {
  const isSuccess = type === 'success';
  const colorClass = isSuccess ? 'text-neon-green border-neon-green' : 'text-red-500 border-red-500';
  const bgClass = isSuccess ? 'bg-neon-green/10' : 'bg-red-900/20';

  return (
    <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-[100] backdrop-blur-sm animate-in fade-in duration-200">
      <div className={`w-[400px] bg-black border ${colorClass} p-6 rounded-xl shadow-[0_0_50px_rgba(0,0,0,0.5)] relative`}>
        <div className="flex items-center gap-3 mb-4 border-b border-gray-800 pb-4">
            {isSuccess ? <CheckCircle className="text-neon-green" /> : <AlertTriangle className="text-red-500" />}
            <h3 className={`text-xl font-bold uppercase tracking-wider ${isSuccess ? 'text-neon-green' : 'text-red-500'}`}>
                {title}
            </h3>
        </div>
        
        <p className="text-gray-300 text-sm mb-8 leading-relaxed font-mono">
            {message}
        </p>

        <div className="flex justify-end gap-4">
            {onConfirm ? (
                <>
                    <button onClick={onClose} className="px-4 py-2 border border-gray-600 text-gray-400 hover:text-white rounded uppercase text-xs font-bold transition">Cancel</button>
                    <button onClick={onConfirm} className={`px-6 py-2 ${isSuccess ? 'bg-neon-green text-black' : 'bg-red-600 text-white'} font-bold rounded uppercase text-xs hover:opacity-90 transition shadow-lg`}>
                        Confirm
                    </button>
                </>
            ) : (
                <button onClick={onClose} className={`w-full py-3 ${isSuccess ? 'bg-neon-green text-black' : 'bg-red-600 text-white'} font-bold rounded uppercase text-xs tracking-widest hover:opacity-90 transition`}>
                    Acknowledge
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

export default SciFiAlert;
